INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('sozialhilfe-neu-sozialausschuss-2-dezember-2026-reform-protest','Sozialhilfe neu: Sozialausschuss berät Reform am 2. Dezember','Der Sozialausschuss des Nationalrats soll am 2. Dezember die Sozialhilfe-Reform behandeln. Hilfsorganisationen kündigen Pressekonferenz und Protest an.','Die **Sozialhilfe neu** steht vor der nächsten Hürde im Parlament: Am Mittwoch, 2. Dezember 2026, soll sich der Sozialausschuss des Nationalrats mit der Regierungsvorlage zur Reform der Sozialhilfe befassen. Das geht aus der Wochenvorschau der Parlamentskorrespondenz vom 27. November hervor. Parallel dazu kündigen Hilfsorganisationen Protestaktionen und eine gemeinsame Pressekonferenz an.

## Sozialhilfe neu: Was im Sozialausschuss am Programm steht

Laut Parlamentskorrespondenz beginnt die Sitzung um 13.30 Uhr. Die Tagesordnung ist noch nicht endgültig fixiert. Zugewiesen sind dem Ausschuss neben der Sozialhilfe-Reform auch eine Novelle des Verbrechensopfergesetzes. Zusätzlich könnten ein neuer Betriebszuschuss für Jungmütter in Höhe von 550 Euro sowie eine Reparatur im Arbeitslosenversicherungsgesetz behandelt werden. Letztere betrifft Nachzahlungen des AMS an Bezieherinnen und Bezieher von Arbeitslosengeld und Notstandshilfe.

Wann der Nationalrat im Plenum abstimmt, ist noch offen. Die Präsidialkonferenz legt die Tagesordnungen der kommenden Plenarsitzungen am Donnerstag, 3. Dezember, fest. Die Regierung hatte nach dem Ministerrat am 17. November angekündigt, die Sozialhilfe-Reform gemeinsam mit rund 30 weiteren Vorhaben im Dezember-Plenum beschließen zu wollen.

## Die Eckpunkte der Reform

Die Koalition aus ÖVP, SPÖ und NEOS hatte ihren Entwurf Ende Oktober präsentiert und in Begutachtung geschickt. Die wichtigsten Punkte laut damaliger Vorstellung:

- Statt bisheriger Höchstsätze sollen **Fixbeträge** gelten. Erwerbsfähige Personen erhalten zunächst einen Basisbetrag, die volle Leistung gibt es nur bei nachgewiesenen Integrationsbemühungen.
- Bei Verstößen gegen Integrationspflichten sind Kürzungen um mindestens 25 Prozent bis hin zur völligen Streichung vorgesehen.
- Ausgenommen von dieser Staffelung sind unter anderem Kinder, Pensionisten, Personen mit Betreuungspflichten und nicht arbeitsfähige Menschen mit Behinderung.
- Für Alleinerziehende sollen bundesweit verpflichtende Zuschläge kommen, die Familienbeihilfe wird nicht angerechnet.
- Geplant ist außerdem eine „Teilhabekarte“ für Familien mit niedrigem Einkommen.

Das Gesetz soll mit 2027 in Kraft treten, die Bundesländer bekommen danach mehrere Monate Zeit für die Umsetzung.

## Verknüpfung mit dem neuen Integrationsprogramm

Eng verzahnt ist die Reform mit dem verpflichtenden Integrationsprogramm für Asylberechtigte, das der Innenausschuss am 25. November mit den Stimmen von ÖVP, SPÖ und NEOS gebilligt hat. Es sieht einen individuellen Integrationsplan, regelmäßige Fortschrittsgespräche beim Österreichischen Integrationsfonds und Kurse zu Deutsch, Werten und Arbeitsmarkt vor. Wer sich den Pflichten schuldhaft entzieht, muss mit Geldstrafen und Kürzungen der Sozialhilfe rechnen. FPÖ und Grüne übten im Ausschuss Kritik. Auch das Integrationsprogramm soll grundsätzlich mit 1. Jänner 2027 gelten.

## Hilfsorganisationen kündigen Protest an

Gegen die Pläne formiert sich Widerstand aus dem Sozialbereich. Caritas, Diakonie, Rotes Kreuz und Volkshilfe laden für Montag, 30. November, zu einer gemeinsamen Pressekonferenz in Wien-Neubau. Die Organisationen befürchten einen Wettlauf der Bundesländer nach unten und kritisieren Wartefristen für die Integration. Sie erinnern daran, dass im Regierungsprogramm eine Kindergrundsicherung und die Halbierung der Kinderarmut bis 2030 angekündigt worden seien. Die Volkshilfe hatte zuletzt auch mit einem [Unterstützungsfonds für pflegende Angehörige](/artikel/pflegende-angehoerige-volkshilfe-fonds-1000-euro-2026) auf soziale Notlagen aufmerksam gemacht.

Die Armutskonferenz plant am Tag der Ausschusssitzung um 10 Uhr eine Aktion vor dem Parlament am Dr.-Karl-Renner-Ring. Unter dem Motto „Bausteine für eine neue Sozialhilfe“ fordert sie unter anderem tragbare Wohnkosten, Härtefallregeln, kürzere Entscheidungsfristen der Behörden und mehr Rücksicht auf Menschen mit psychischen Erkrankungen sowie gewaltbetroffene Frauen.

## Wie es weitergeht

Passiert die Vorlage den Sozialausschuss, ist der Weg ins Plenum frei. Wie zuletzt bei der [Medienförderung im Nationalrat](/artikel/medienfoerderung-nationalrat-18-november-2026-print-zustellung-oebb) entscheidet die Präsidialkonferenz über den konkreten Sitzungstermin. Für die Sozialhilfe-Reform ist keine Zweidrittelmehrheit nötig, die Koalition kann sie also mit eigener Mehrheit beschließen. Danach müssen die Länder ihre Sozialhilfegesetze anpassen.','politik','Innenpolitik',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/sozialhilfe-neu-sozialausschuss-2-dezember-2026-reform-protest.webp','Parlamentskorrespondenz (PK Nr. 1165, 27.11.2026)','https://www.ots.at/presseaussendung/OTS_20261127_OTS0116/die-parlamentswoche-vom-30-november-bis-4-dezember-2026','published','2026-11-28T11:55:00.000Z','2026-11-28T11:55:00.000Z','Sozialhilfe neu: Ausschuss am 2. Dezember','Sozialhilfe neu: Der Sozialausschuss berät am 2. Dezember die Reform. Alle Eckpunkte, der Zeitplan bis 2027 und die Kritik von Caritas & Co. im Überblick.','Sozialhilfe neu','["Sozialhilfe neu","Sozialhilfe Reform","Sozialhilfe 2027","Sozialausschuss Nationalrat","Sozialhilfe Reform Österreich Zeitplan","Integrationsprogramm Asylberechtigte","Sozialhilfe Kürzung Integrationspflicht","Caritas Volkshilfe Sozialhilfe Kritik"]','Sozialhilfe neu: Parlamentsgebäude in Wien an einem grauen Novembermorgen','Neoclassical government building in Vienna with tall columns on a cold grey late-November morning, wet pavement, a few blurred pedestrians with umbrellas far away, stacks of paper documents not visible, documentary photography, Austrian context, no text, no logos, no readable signs','[{"q":"Wann berät der Sozialausschuss die Sozialhilfe neu?","a":"Laut Parlamentskorrespondenz am Mittwoch, 2. Dezember 2026, ab 13.30 Uhr. Die Tagesordnung war zuletzt noch nicht endgültig."},{"q":"Ab wann soll die neue Sozialhilfe gelten?","a":"Die Reform soll mit 2027 in Kraft treten. Die Bundesländer erhalten danach mehrere Monate Zeit, ihre Gesetze anzupassen."},{"q":"Wer kritisiert die Reform?","a":"Unter anderem Caritas, Diakonie, Rotes Kreuz, Volkshilfe und die Armutskonferenz. Sie warnen vor Kürzungen und Wartefristen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
